sealed class Parser(List<Token> toks) {          // Token = record(TokenKind Kind, string Text, int Pos)
    int _pos;
    Token Peek(int k = 0) => toks[_pos + k];
    Token Expect(TokenKind k) => Peek().Kind == k
        ? toks[_pos++] : throw new ParseError($"expected {k} at {Peek().Pos}");
    Node Expr() {
        var left = Term();
        while (Peek().Kind is TokenKind.Plus or TokenKind.Minus)   // loop, not left recursion
            left = new Binary(toks[_pos++].Kind, left, Term());
        return left;
    }
}
